// Daily change briefing (briefing-1.0). Every statement in a briefing is generated by fixed rules from stored data and carries a numbered citation.
// There is no model-written text and no score. Wording is "coincident, not causal".

export const BRIEFING_VERSION = 'briefing-1.0';

export interface Citation {
  n: number;
  kind: 'item' | 'contract' | 'sensor' | 'alert' | 'claim' | 'hypothesis' | 'dossier' | 'calendar' | 'wallet_trade' | 'source';
  label: string;
  url: string | null;
  /** Stable internal reference (feed key, condition id, alert id …) so the citation can be opened in the app. */
  ref: string | null;
  outlet: string | null;
  tier: string | null;
  published_at: string | null;
  collected_at: string | null;
}

export interface BriefingWindow { from: string; to: string; hours: number; basis: 'publication time' }

export interface BriefingItem { n: number; event_id: string; title: string; outlet: string; tier: string; published_at: string; collected_at: string; affiliation: string; language: string; untranslated: boolean }
export interface BriefingStory {
  title: string; first_published_at: string; items: BriefingItem[]; items_total: number; independence_groups: number; state_only: boolean; single_outlet: boolean;
  touches: { n: number; question: string; venue: string; score: number }[];
}
export interface BriefingContract {
  n: number; condition_id: string; venue: string; question: string; price_pct: number | null; quote_basis: string | null;
  change_24h_pp: number | null; change_from_t: number | null; change_to_t: number | null;
  change_basis: 'history' | 'provider_reported'; hourly: { label: string; current_pp: number | null; p95_pp: number | null } | null; reasons: string[];
  items: { n: number; outlet: string; published_at: string }[];
}
export interface BriefingSensor { n: number; title: string; value: string; observed_at: string | null; change: string | null; status: string; reason: string | null }
export interface BriefingAlert { n: number; title: string; severity: string; opened_at: string; open: boolean; rule_id: string; definition_version: string; detail: string }
export interface BriefingResearchChange { n: number | null; kind: string; text: string; at: string }
export interface BriefingUpcoming { n: number; title: string; when: string; precision: 'instant' | 'date'; basis: string }
export interface BriefingTrade { n: number; question: string; side: string; outcome: string; notional_usdc: number; at: string; wallet: string; criteria: string[] }

export interface Briefing {
  version: typeof BRIEFING_VERSION;
  generated_at: string;
  window: BriefingWindow;
  seed_mode: boolean;
  summary: string[];
  stories: BriefingStory[];
  stories_omitted: number;
  late_collected: number;
  telegram_posts: number;
  contracts: BriefingContract[];
  contracts_checked: number;
  contracts_not_computable: { reason: string; count: number }[];
  sensors: BriefingSensor[];
  alerts: BriefingAlert[];
  research: BriefingResearchChange[];
  upcoming: BriefingUpcoming[];
  large_trades: BriefingTrade[];
  limits: string[];
  citations: Citation[];
}

export interface SavedBriefingRow { id: string; saved_at: string; window_from: string; window_to: string; note: string }
